-- 数据统计
SELECT '用户' AS 表名, COUNT(*) AS 数量 FROM user
UNION ALL SELECT '分类', COUNT(*) FROM category
UNION ALL SELECT 'Banner', COUNT(*) FROM banner
UNION ALL SELECT '商品', COUNT(*) FROM goods
UNION ALL SELECT 'SKU', COUNT(*) FROM goods_sku;

SELECT '种子数据导入完成！' AS result;
